    }
  ],
  "relationship_delta": [
    {
      "relationship": "林岚与周野的合作模式",
      "before": "周野试图帮忙但缺乏专业知识，林岚刻意保持距离并冷声制止。",
      "after": "周野接受后勤角色负责递送工具，林岚默许他的陪伴，防备在旧日回忆中有所消融。"
